import { createAudioPlayer, type AudioPlayer } from 'expo-audio';

export type BellId = 'bowl' | 'gong' | 'chimes' | 'marimba';

/** The meditation end-bell sounds (generated by scripts/make-chime.mjs, shipped in res/raw as bell_<id>.wav). */
export const BELLS: { id: BellId; label: string; description: string; asset: number }[] = [
  { id: 'bowl', label: 'Singing bowl', description: 'Three warm strikes', asset: require('../../assets/sounds/bell_bowl.wav') },
  { id: 'gong', label: 'Temple gong', description: 'Deep and slowly fading', asset: require('../../assets/sounds/bell_gong.wav') },
  { id: 'chimes', label: 'Wind chimes', description: 'Light and airy', asset: require('../../assets/sounds/bell_chimes.wav') },
  { id: 'marimba', label: 'Soft marimba', description: 'A gentle wooden melody', asset: require('../../assets/sounds/bell_marimba.wav') },
];

export const DEFAULT_BELL: BellId = 'bowl';
export const bellById = (id: string | undefined) => BELLS.find((b) => b.id === id) ?? BELLS[0];

let preview: AudioPlayer | null = null;

/** Play a bell once from the app (previews, and the fallback when the native alarm isn't available). */
export function playBell(id: BellId) {
  stopBellPreview();
  try {
    preview = createAudioPlayer(bellById(id).asset);
    preview.play();
  } catch {
    preview = null;
  }
}

export function stopBellPreview() {
  if (!preview) return;
  try {
    preview.pause();
    preview.remove();
  } catch {
    // already released
  }
  preview = null;
}
